    var count = 1;
    var result = "";
    var len = std::str::len(s);
    for i in 1..len {
        var c = std::str::char_at(s, i);
        if c == current_char {
            count += 1;
        } else {
            result = result + current_char + std::num::to_string(count);
            current_char = c;
            count = 1;
        }
    }
    result = result + current_char + std::num::to_string(count);
    return result;
}

